$mutated = function (array $block, array $changes): array {
    foreach ($changes as $change) {
        $path = implode('.', $change['path']);
        if ($change['delete'] ?? false) {
            Arr::forget($block, $path);
        } else {
            $target = &$block;
            foreach ($change['path'] as $segment) {
                $target = &$target[$segment];
            }
            $target = $change['value'];
            unset($target);
        }
    }

    return $block;
};

$run = function (array $case) use ($official, $variables, $mutated): mixed {
    return match ($case['op']) {
        'define' => BlockDefinition::define($case['kind'], $mutated($official['blocks'][$case['kind']], $case['set']), ($case['novars'] ?? false) ? [] : $variables),
        'read' => RepeatableTable::read($case['kind'], BlockDefinition::define($case['kind'], $official['blocks'][$case['kind']], $variables), $variables),
        'key' => RepeatableTable::key($case['text'], 'columna', []),
        'build' => (function () use ($case, $variables): array {
            $design = RepeatableTable::withKeys($case['design']);
            $block = BlockDefinition::define((string) $design['kind'], RepeatableTable::build($design), $variables);

            return ['kind' => $design['kind'], 'definition' => $block, 'design' => RepeatableTable::read((string) $design['kind'], $block, $variables)['design'] ?? $design, 'initial' => ValueSchema::initial($block['value'], [])];
        })(),
    };
};

$cases = [];
foreach ($descriptors as $case) {
    try {
        $expected = json_encode(['ok' => $run($case)]);
    } catch (ValidationException $exception) {
        $expected = json_encode(['errors' => $exception->errors()]);
    }
    if (preg_match('/\de-\d/', $expected) === 1) {
        continue;
    }
    $cases[] = [...$case, 'expected' => $expected];
}

file_put_contents(__DIR__.'/block-golden.json', json_encode([
    'variables' => $variables,
    'blocks' => $official['blocks'],
    'designs' => json_encode(TemplatePresentation::blockDesigns(OfficialTemplate::definition())),
    'cases' => $cases,
], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)."\n");
